import{_ as s,k as t,C as n,a6 as a,A as o,j as l}from"./chunks/framework.BWVK1BSo.js";const m=JSON.parse('{"title":"Plugins Explained","description":"The basics of plugins.","frontmatter":{"title":"Plugins Explained","page_title":"Plugins Explained","description":"The basics of plugins.","category":"Guide","nav_order":1,"prefix":"1. ","mentions":["8Crafter"]},"headers":[{"level":2,"title":"What Are Plugins?","slug":"what-are-plugins","link":"#what-are-plugins","children":[]}],"relativePath":"plugins/plugins.md","filePath":"plugins/plugins.md"}'),r={name:"plugins/plugins.md"};function p(c,e,u,d,h,f){const i=o("template-WorkInProgress");return l(),t("div",null,[n(i),e[0]||(e[0]=a('<h2 id="what-are-plugins" tabindex="-1">What Are Plugins? <a class="header-anchor" href="#what-are-plugins" aria-label="Permalink to &quot;What Are Plugins?&quot;">​</a></h2><p>A plugin allows you to add, modify, and remove functionality from the Ore UI Customizer.</p><p>The way plugins work is by operating on the Ore UI files, like the Ore UI Customizer does.</p><p>It is highly recommended to write plugins in TypeScript, but they can also be written in JavaScript.</p><p>There are two types of plugins: single-file and multi-file.</p><p>Multi-file plugins come in a <code class="shiki"><span>.ouicplugin</span></code> or <code class="shiki"><span>.mcouicplugin</span></code> file, while single-file plugins come in a <code class="shiki"><span>.js</span></code> file.</p><p>An <code class="shiki"><span>.ouicplugin</span></code>/<code class="shiki"><span>.mcouicplugin</span></code> file is actually a renamed zip file.</p><p>It is recommended to use multi-file plugins, but you can read more about single-file plugins <a href="./single-file-plugins">here</a>.</p><p>All multi-file plugins contain a script file in the <code class="shiki"><span>scripts</span></code> folder that runs and exports a list of &quot;actions&quot;. These actions are run by the Ore UI Customizer during the installation process. These actions can add, modify, and remove files from the Ore UI files.</p><p>These script files in the <code class="shiki"><span>scripts</span></code> folder should be cross-compatible between browser and Node.js. This is because there are 3 official environments plugins can be run in, the Ore UI Customizer website (web only), the Ore UI Customizer app (web + Node.js), and the Ore UI Customizer CLI (Node.js only).</p><p>NOTE: Plugins in the <code class="shiki"><span>scripts</span></code> folder currently are not capable of importing other scripts contained in the plugin via their path due to being imported via data URI, so you should put all install-time code into a single file in the <code class="shiki"><span>scripts</span></code> folder.</p><p>If you want a script file that runs in-game, you would put it in the <code class="shiki"><span>assets</span></code> folder, and you would add that file to the Ore UI files via a plugin action, and you would also inject an import statement into either the HTML files for the screens that you want to run the script file in, or into one of the script files that are imported by those HTML files. For more info, see <a href="./client-scripts">Client Scripts</a>.</p>',12))])}const _=s(r,[["render",p]]);export{m as __pageData,_ as default};
